internal data class ReplaySettlementObservation(val receipt: JsonObject, val beforeConstruction: String?,
    val construction: String?, val retained: Pair<Int, Long>)

internal open class ReplaySqlStructuralTest : SurvivorTestSupport() {
    @Test fun settlementUsesDescriptionsWithoutChangingSqlOrCharges() = runOwnedWebDatabaseTest(timeout=180.seconds) {
        observeCommittedReplay(0, null)
    }

    protected suspend fun observeCommittedReplay(size: Int, construction: ReplayConstructionObservation?): ReplaySettlementObservation {
            var result: ReplaySettlementObservation? = null
            construction?.reset()
            val path = createTempSqliteNowTestDbPath("replay-description-$size")
            try {
                withSurvivorFixture(workUnits = 5_000_000, dbPath = path) { server, db, _, client ->
                    try {
                        db.execSQL("UPDATE nodes SET name='changed parent' WHERE id='P'")
                        server.normalizePushEffects = { effects() }
                        server.beforePushResponse = { throw CancellationException("lost committed response") }
                        assertFailsWith<CancellationException> { client.pushPending().getOrThrow() }
                        val frozen = server.pushBodies.last()
                        // Add unrelated dirty intent only after the one-row upload is frozen.
                        db.transaction {
                            repeat(size) { db.execSQL("INSERT INTO nodes VALUES('Z${it.toString().padStart(5, '0')}','${"x".repeat(16)}',NULL)") }
                        }
                        val unrelatedSql = "SELECT coalesce(json_group_array(payload),'[]') FROM (SELECT payload FROM _sync_dirty_rows WHERE json_extract(key_json,'$.id') LIKE 'Z%' ORDER BY key_json)"
                        val unrelated = scalarText(db, unrelatedSql)
                        val observer = ReplaySqlObservation.install(db)
                        val cachedSql = mutableListOf<String>()
                        val owner = replayValidatedOwner(client)
                        val beforeConstruction = construction?.snapshot()
                        val retainedBefore = replayRetainedDescriptions(owner.replaySql)
                        client.setSnapshotApplyFaultInjectorForTest(SnapshotApplyFaultInjector(statementCacheOperations = StatementCacheOperations(
                            prepare = { connection, sql -> cachedSql += sql; connection.prepare(sql) },
                        )))
                        try { client.pushPending().getOrThrow() }
                        finally { client.setSnapshotApplyFaultInjectorForTest(null); observer.restore() }
                        val constructionSnapshot = construction?.snapshot()
                        requireSurvivors(db)
                        assertEquals(frozen, server.pushBodies.last())
                        assertEquals(3, server.pushRequestCount)
                        assertEquals(3L, scalarLong(db, "SELECT next_source_bundle_id FROM _sync_source_state"))
                        assertEquals(2L, scalarLong(db, "SELECT last_bundle_seq_seen FROM _sync_attachment_state"))
                        assertEquals(0L, scalarLong(db, "SELECT count(*) FROM _sync_outbox_rows"))
                        assertEquals(size.toLong(), scalarLong(db, "SELECT count(*) FROM _sync_dirty_rows"))
                        assertEquals(unrelated, scalarText(db, unrelatedSql))
                        assertEquals(0L, scalarLong(db, "SELECT reserved_entries+reserved_bytes FROM _sync_operation_state"))
                        assertTrue(observer.selectedExecutions > 0)
                        assertTrue(observer.counts.keys.any { ReplaySqlObservation.selected(it) && it !in cachedSql }, "uncached business queries observed")
                        assertTrue(cachedSql.any { it.contains("FROM _sync_operation_state o") }, "real settlement cache observed")
                        observer.counts.forEach { (sql, count) -> assertEquals(count.prepares, count.closes, "all observed handles closed: $sql") }
                        val durable = baselineQualificationVector(db, listOf("nodes"))
                        client.closeFromCoordinatedOwner()
                        db.close()
                        val reopened = newFileBackedDb(path)
                        try { assertEquals(durable, baselineQualificationVector(reopened, listOf("nodes"))) }
                        finally { reopened.close() }
                        val retainedAfter = replayRetainedDescriptions(owner.replaySql)
                        assertEquals(retainedBefore, retainedAfter, "row work cannot grow retained descriptions")
                        val receipt = buildJsonObject {
                            put("size", size); put("bindingTrace", observer.bindingTraceHash())
                            put("selectedExecutions", observer.selectedExecutions)
                            put("accounting", client.workspaceDiagnostics().toString())
                            put("sql", buildJsonObject { observer.counts.toSortedMap().forEach { (sql, c) ->
                                put(sql, buildJsonObject { put("prepares", c.prepares); put("steps", c.steps); put("resets", c.resets); put("clears", c.clears); put("closes", c.closes) })
                            } })
                            put("construction", constructionSnapshot?.let(Json::parseToJsonElement) ?: JsonNull)
                        }
                        assertReplayOracle(size, receipt)
                        println("REPLAY_SQL_RECEIPT " + receipt)
                        result = ReplaySettlementObservation(receipt, beforeConstruction, constructionSnapshot, retainedAfter)
                    } finally { client.closeFromCoordinatedOwner() }
                }
            } finally { deleteTempSqliteNowTestDbArtifacts(path) }
            return checkNotNull(result)
    }

    @Test fun refusalCancellationAndRetryKeepFreshValues() = runOwnedWebDatabaseTest(timeout=180.seconds) {
        val refusalPath = createTempSqliteNowTestDbPath("replay-refusal")
        try {
            withSurvivorFixture(dbPath=refusalPath) { server,db,http,seed ->
                try {
                    db.execSQL("UPDATE nodes SET name='changed parent' WHERE id='P'")
                    server.beforePushCommit={ throw CancellationException("frozen original") }
                    assertFailsWith<CancellationException> { seed.pushPending().getOrThrow() }
                    val hash=scalarText(db,"SELECT canonical_request_hash FROM _sync_outbox_bundle")
                    val request=server.pushBodies.last()
                    seed.closeFromCoordinatedOwner()
                    val limited=newClient(db,http,syncTables=nodeTables,workUnits=1000)
                    try {
                        limited.openAndConnect("user-1").getOrThrow()
                        server.normalizePushEffects={effects()}
                        val protected=protectedPrimaryVector(db)
                        val owner=replayValidatedOwner(limited)
                        limited.setSnapshotApplyFaultInjectorForTest(SnapshotApplyFaultInjector(beforeCommit = {
                            throw CancellationException("cancel frozen replay preparation")
                        }))
                        try { assertFailsWith<CancellationException> { limited.pushPending().getOrThrow() } }
                        finally { limited.setSnapshotApplyFaultInjectorForTest(null) }
                        assertEquals(protected,protectedPrimaryVector(db))
                        assertSame(owner,replayValidatedOwner(limited))
                        assertEquals(hash,scalarText(db,"SELECT canonical_request_hash FROM _sync_outbox_bundle"))
                        assertEquals(request,server.pushBodies.last())
                        assertEquals(1L,scalarLong(db,"SELECT last_bundle_seq_seen FROM _sync_attachment_state"))
                        assertEquals(0L,scalarLong(db,"SELECT reserved_entries+reserved_bytes+apply_mode FROM _sync_operation_state CROSS JOIN _sync_apply_state"))
                    } finally { limited.closeFromCoordinatedOwner() }
                    val resumed=newClient(db,http,syncTables=nodeTables)
                    try {
                        resumed.openAndConnect("user-1").getOrThrow()
                        db.execSQL("UPDATE nodes SET name='latest 猫' WHERE id='D'")
                        val before = protectedPrimaryVector(db)
                        val observer = ReplaySqlObservation.install(db)
                        var cancelled = 0
                        resumed.setSnapshotApplyFaultInjectorForTest(SnapshotApplyFaultInjector(beforeCommit = {
                            cancelled++; throw CancellationException("settlement descriptions cancelled")
                        }))
                        try { assertEquals("settlement descriptions cancelled", assertFailsWith<CancellationException> { resumed.pushPending() }.message) }
                        finally { resumed.setSnapshotApplyFaultInjectorForTest(null); observer.restore() }
                        assertEquals(1, cancelled)
                        assertEquals(before, protectedPrimaryVector(db), "settlement cancellation rolls back roots, cursors, charges and primary values")
                        assertEquals(1L, observer.counts["ROLLBACK"]?.steps)
                        observer.counts.forEach { (sql,c) -> assertEquals(c.prepares,c.closes,"owned cleanup: $sql") }
                        resumed.pushPending().getOrThrow()
                        assertEquals("Q",scalarText(db,"SELECT parent_id FROM nodes WHERE id='C'"))
                        assertEquals("C",scalarText(db,"SELECT parent_id FROM nodes WHERE id='D'"))
                        assertEquals("latest 猫",scalarText(db,"SELECT name FROM nodes WHERE id='D'"))
                        assertEquals(0L,scalarLong(db,"SELECT count(*) FROM nodes WHERE id='P'"))
                        assertEquals(1L,scalarLong(db,"SELECT count(*) FROM _sync_dirty_rows"))
                        assertEquals(0L,scalarLong(db,"SELECT count(*) FROM pragma_foreign_key_check"))
                        assertEquals(3L,scalarLong(db,"SELECT next_source_bundle_id FROM _sync_source_state"))
                        assertEquals(2L,scalarLong(db,"SELECT last_bundle_seq_seen FROM _sync_attachment_state"))
                        assertEquals(0L,scalarLong(db,"SELECT count(*) FROM _sync_outbox_rows"))
                        val durable=baselineQualificationVector(db,listOf("nodes"))
                        resumed.closeFromCoordinatedOwner(); db.close()
                        val reopened=newFileBackedDb(refusalPath)
                        try { assertEquals(durable,baselineQualificationVector(reopened,listOf("nodes"))) } finally { reopened.close() }
                    } finally { resumed.closeFromCoordinatedOwner() }
                } finally { seed.closeFromCoordinatedOwner() }
            }
        } finally { deleteTempSqliteNowTestDbArtifacts(refusalPath) }

        val path=createTempSqliteNowTestDbPath("replay-pending-cancel")
        try {
            withSurvivorFixture(dbPath=path) { server,db,http,seed ->
                try {
                    db.execSQL("UPDATE _sync_apply_state SET apply_mode=1")
                    repeat(250) { db.execSQL("INSERT INTO nodes VALUES('Z${it.toString().padStart(5,'0')}','unrelated',NULL)") }
                    db.execSQL("UPDATE _sync_apply_state SET apply_mode=0")
                    seed.closeFromCoordinatedOwner()
                    server.addRemoteBundleForTest(effects())
                    var previousCursor: String?=null
                    repeat(2) {
                        val limited=newClient(db,http,syncTables=nodeTables,workUnits=1800)
                        try {
                            limited.openAndConnect("user-1").getOrThrow()
                            interruptApplyAfterCommittedSlice(limited) { limited.pullToStable().getOrThrow() }
                            assertEquals(applyUnit("pull",2,computeCommittedBundleHashForTest(effects())), scalarText(db,"SELECT unit FROM _sync_apply_plan"))
                            assertEquals(2L,scalarLong(db,"SELECT root_cursor FROM _sync_apply_plan"))
                            assertEquals("index",scalarText(db,"SELECT phase FROM _sync_apply_plan"))
                            val cursor=scalarText(db,"SELECT row_cursor FROM _sync_apply_plan")
                            previousCursor?.let { assertTrue(cursor>it, "saved discovery advances across owners") }; previousCursor=cursor
                            assertEquals(1L,scalarLong(db,"SELECT last_bundle_seq_seen FROM _sync_attachment_state"))
                            assertEquals(0L,scalarLong(db,"SELECT apply_mode FROM _sync_apply_state"))
                            assertEquals(scalarLong(db,"SELECT sum(bytes) FROM _sync_apply_rows"),scalarLong(db,"SELECT bytes FROM _sync_apply_plan"))
                            assertEquals(scalarLong(db,"SELECT count(*) FROM _sync_apply_rows"),scalarLong(db,"SELECT entries FROM _sync_apply_plan"))
                            assertEquals(scalarLong(db,"SELECT sum(bytes) FROM _sync_apply_edges"),scalarLong(db,"SELECT edge_bytes FROM _sync_apply_plan"))
                        } finally { limited.closeFromCoordinatedOwner() }
                    }
                    val client=newClient(db,http,syncTables=nodeTables)
                    try {
                        client.openAndConnect("user-1").getOrThrow()
                        val owner=replayValidatedOwner(client)
                        val description=owner.replaySql.table("nodes")
                        val shape=description.liveSelect
                        val before=protectedPrimaryVector(db)
                        val observer=ReplaySqlObservation.install(db)
                        var reached=0
                        client.setSnapshotApplyFaultInjectorForTest(SnapshotApplyFaultInjector(beforeCommit={reached++;throw CancellationException("description replay cancelled")}))
                        try { assertEquals("description replay cancelled", assertFailsWith<CancellationException> {client.pullToStable()}.message) }
                        finally { client.setSnapshotApplyFaultInjectorForTest(null);observer.restore() }
                        assertEquals(1,reached)
                        assertEquals(before,protectedPrimaryVector(db),"cancelled mutation rolls back complete saved plan and typed values")
                        assertEquals(1L,observer.counts["ROLLBACK"]?.steps)
                        observer.counts.forEach { (sql,c) -> assertEquals(c.prepares,c.closes,"owned cleanup: $sql") }
                        assertSame(shape,description.liveSelect)
                        client.pullToStable().getOrThrow()
                        assertEquals("grandchild",scalarText(db,"SELECT name FROM nodes WHERE id='D'"))
                        assertEquals("C",scalarText(db,"SELECT parent_id FROM nodes WHERE id='D'"))
                        assertEquals(0L,scalarLong(db,"SELECT count(*) FROM _sync_apply_plan"))
                        assertEquals(2L,scalarLong(db,"SELECT last_bundle_seq_seen FROM _sync_attachment_state"))
                        assertEquals(0L,scalarLong(db,"SELECT apply_mode FROM _sync_apply_state"))
                        assertEquals(0L,scalarLong(db,"SELECT count(*) FROM pragma_foreign_key_check"))
                        val durable=baselineQualificationVector(db,listOf("nodes"))
                        client.closeFromCoordinatedOwner(); db.close()
                        val reopened=newFileBackedDb(path)
                        try {assertEquals(durable,baselineQualificationVector(reopened,listOf("nodes")))}finally{reopened.close()}
                    } finally {client.closeFromCoordinatedOwner()}
                } finally {seed.closeFromCoordinatedOwner()}
            }
        } finally {deleteTempSqliteNowTestDbArtifacts(path)}
    }

    internal fun assertReplayOracle(size: Int, actual: JsonObject) {
        val resource = checkNotNull(javaClass.getResource("/replay-current-schema-oracles.json"))
        val baseline = Json.parseToJsonElement(resource.readText()).jsonObject
        assertEquals("5862f8b23c665971b81f08c52774da012f2b0241", baseline.getValue("sourceHead").jsonPrimitive.content)
        val expected = baseline.getValue("cases").jsonArray.map { it.jsonObject }.single { it.getValue("size").jsonPrimitive.int == size }
        for (key in listOf("bindingTrace", "selectedExecutions", "accounting"))
            assertEquals(expected[key], actual[key], "immutable untouched-source oracle size=$size field=$key")
        assertEquals(decisionBindingSqlOracle(boundedCleanupSqlOracle(expected.getValue("sql").jsonObject)), actual["sql"],
            "untouched-source SQL oracle plus declared cleanup grouping and decision binding size=$size")
    }

    // This fixture freezes one root: its node removal and final owner deletion
    // formerly needed two writers. The declared 32-record batch uses one writer.
    // Derive only those four physical calls; every other frozen SQL, binding,
    // accounting and durable-state assertion remains unchanged.
    private fun boundedCleanupSqlOracle(original: JsonObject): JsonObject {
        val removedWriters = 2 - ((2 + 31) / 32)
        val shapes = setOf("BEGIN IMMEDIATE", "COMMIT",
            "SELECT COALESCE(json_extract(state,'$.cleanupDiagnosticId'),'') FROM _sync_push_plan WHERE singleton_key=1",
            "SELECT unit,guard,phase,entries,bytes,length(CAST(state AS BLOB)) FROM _sync_push_plan WHERE singleton_key=1")
        assertTrue(original.keys.containsAll(shapes))
        return JsonObject(original.mapValues { (sql, value) ->
            if (sql !in shapes) value else JsonObject(value.jsonObject.mapValues { (counter, count) ->
                if (counter !in setOf("prepares", "steps", "closes")) count else {
                    val baseline = count.jsonPrimitive.long
                    assertTrue(baseline >= removedWriters)
                    JsonPrimitive(baseline - removedWriters)
                }
            })
        })
    }

    // The frozen upload has one changed P and one non-uploaded C effect: two
    // decision records in one writer. Binding reuse removes one full guard pair.
    // finishDecisionBinding performs one extra validated ledger load/store before
    // mutation. The record-validation statement steps once for its row and once
    // for exhaustion. No other SQL, binding trace or work accounting changes.
    private fun decisionBindingSqlOracle(original: JsonObject): JsonObject {
        val guardShapes = original.keys.filter { it.startsWith("SELECT 8192+6*") ||
            it.startsWith("SELECT i.database_id,i.service_id,i.generation_id") }.toSet()
        val ledgerShapes = original.keys.filter { it.startsWith("SELECT reserved_entries,reserved_bytes,workspace_context") ||
            it.startsWith("SELECT count(*),count(DISTINCT json_extract(j.value,'$.token'))") ||
            it.startsWith("SELECT json_type(workspace_context)") || it.startsWith("SELECT json_type(j.value)") ||
            it.startsWith("UPDATE _sync_operation_state SET workspace_context=?") }.toSet()
        assertEquals(2, guardShapes.size)
        assertEquals(6, ledgerShapes.size)
        val removedGuards = 2L - 1L
        return JsonObject(original.mapValues { (sql, value) ->
            if (sql !in guardShapes && sql !in ledgerShapes) value else JsonObject(value.jsonObject.mapValues { (counter, count) ->
                if (counter !in setOf("prepares", "steps", "closes")) count else {
                    val delta = if (sql in guardShapes) -removedGuards else
                        if (counter == "steps" && sql.startsWith("SELECT json_type(j.value)")) 2L else 1L
                    val expected = count.jsonPrimitive.long + delta
                    assertTrue(expected >= 0)
                    JsonPrimitive(expected)
                }
            })
        })
    }

