        listOf(
            "INSERT INTO _sync_apply_plan(",
            "INSERT INTO _sync_apply_rows(",
            "INSERT OR IGNORE INTO _sync_apply_edges",
            "SELECT 1 FROM _sync_apply_rows",
            "SELECT bytes FROM _sync_apply_rows",
            "SELECT pending FROM _sync_apply_rows",
            "SELECT ordinal FROM _sync_apply_rows WHERE pending=1",
            "SELECT table_name,local_pk FROM _sync_apply_rows",
            "SELECT table_name,local_pk,payload,wire FROM _sync_apply_rows",
            "SELECT unit,guard,phase,root_cursor,",
            "UPDATE _sync_apply_rows SET pending=2",
            "SELECT length(CAST(child_pk AS BLOB))",
            "SELECT child_pk FROM _sync_apply_edges",
            "SELECT 64+6*(length(CAST(schema_name",
            "SELECT schema_name,table_name,key_json,payload FROM _sync_dirty_rows",
        ).any(sql::startsWith) ||
            (sql.contains("FROM \"nodes\"") && (sql.startsWith("SELECT 2+") ||
                sql.startsWith("SELECT length(CAST(CAST(") || sql.startsWith("SELECT CAST(\""))) ||
            (sql.startsWith("SELECT json_object(") && sql.contains("FROM \"nodes\" live_row"))

